'use strict';
const page=document.body.dataset.page;
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const photos=window.PCP_IMAGES||{};
const params=new URL(location.href).searchParams;
const validIDs=list=>[...new Set(list)].filter(id=>catalog.some(p=>p.id===id)).slice(0,4);
const series=['var(--chart-a)','var(--chart-b)','var(--chart-c)','var(--chart-d)'];
const photoLabel=a=>"";
const shortName=p=>p.name.replace('GeForce ','').replace('Radeon ','');
const categoryHelp={fan:'Fan sizes, lighting and connections',board:'CPU sockets and expansion',hdd:'High-capacity storage',psu:'Power and connectors',case:'Size and component clearance',monitor:'Resolution and refresh rate',mouse:'Shape, sensor, and weight',keyboard:'Layout and switch type',microphone:'Connection and recording pattern',headset:'Audio and microphone features',controller:'Platform and connection',console:'Console generations',phone:'Mobile hardware',handheld:'Portable gaming systems'};
function announce(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(announce.timer);announce.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function renderEvent(scope){document.dispatchEvent(new CustomEvent('pcp:render',{detail:{scope}}));}
function photo(p,cls='',caption=false){const a=photos[p.id];if(!a)return `<div class="photo-unavailable"><span>${escapeHTML(p.brand)}</span><strong>${escapeHTML(p.architecture)}</strong></div>`;const alt=a.picturedModel;return `<figure class="hardware-photo ${cls}"><img src="${a.src}" alt="${escapeHTML(alt)}" width="800" height="500" decoding="async" loading="lazy"></figure>`;}
function imageCredits(a){if(!a)return '';return `<a href="${escapeHTML(a.sourceUrl)}" target="_blank" rel="noopener">Photo source ↗</a>${a.attribution?`<span class="image-credit">Photo: ${escapeHTML(a.attribution.replace(/<[^>]*>/g,''))}${a.license?` · <a href="${escapeHTML(a.licenseUrl||a.sourceUrl)}" target="_blank" rel="noopener">${escapeHTML(a.license)}</a>`:''}</span>`:''}`;}

function defaultParts(category){const presets={gpu:['rtx5070','rtx5060ti16'],cpu:['7800x3d','9800x3d'],ram:['ddr4','ddr5'],ssd:['990pro','sn850x']};const valid=validIDs(presets[category]||[]).filter(id=>catalog.find(p=>p.id===id)?.cat===category);return valid.length===2?valid:catalog.filter(p=>p.cat===category).sort((a,b)=>(b.year||0)-(a.year||0)).slice(0,2).map(p=>p.id);}
selected=params.has('parts')?validIDs(params.get('parts').split(',')):defaultParts(categories.some(([id])=>id===params.get('category'))?params.get('category'):'gpu');
if(parts()[0])activeCategory=parts()[0].cat;
if(page==='home'&&(params.has('parts')||params.has('build')||['#compare','#builder','#catalog'].includes(location.hash))){location.replace('/'+(params.has('build')||location.hash==='#builder'?'builder':location.hash==='#catalog'?'hardware':'compare')+'/'+location.search);}
if(page==='learn'&&params.has('category'))location.replace('/hardware/?category='+encodeURIComponent(params.get('category')));
function saveComparison(){const url=new URL(location.href);url.searchParams.set('parts',selected.join(','));url.searchParams.delete('category');history.replaceState(null,'',url);try{sessionStorage.setItem('pcp-comparison',JSON.stringify(selected))}catch{}}

function imageCard(p,i){return `<article class="product-card" style="--series:${series[i]}"><div class="product-top"><span class="product-index">PART 0${i+1}</span><button class="icon-button remove-product" data-remove="${p.id}" aria-label="Remove ${escapeHTML(p.name)}">×</button></div><div class="product-image">${photo(p,'',true)}</div><div class="product-heading"><span class="eyebrow">${escapeHTML(p.brand)}${p.year?' · '+p.year:''}</span><h2><a href="/learn/${p.id}.html">${escapeHTML(shortName(p))}</a></h2><p>${escapeHTML(p.summary)}</p><button class="change-product" data-replace="${i}" aria-label="Change ${escapeHTML(p.name)}">Change part <span aria-hidden="true">⌄</span></button></div><div class="product-meta"><span>${escapeHTML(p.architecture)}</span><a href="/learn/${p.id}.html">View part →</a></div></article>`;}
function renderComparison(){
 const ps=parts();$('#comparison-cards').style.setProperty('--count',Math.max(ps.length,2));$('#comparison-cards').innerHTML=ps.map(imageCard).join('')+(ps.length<2?`<button class="empty-product" data-new="true"><span>＋</span><strong>Choose ${ps.length?'another':'your first'} part</strong><small>Search the hardware catalog</small></button>`:'');
 $('#add-comparison').hidden=ps.length>=4;$('#export-csv').disabled=!ps.length;
 $('#compare-categories').innerHTML=[['gpu','Graphics cards'],['cpu','Processors'],['ram','Memory'],['ssd','SSDs']].map(([id,label])=>`<button data-category="${id}" aria-pressed="${activeCategory===id}" class="${activeCategory===id?'active':''}">${label}</button>`).join('');
 const moreCategories=categories.filter(([id])=>!['gpu','cpu','ram','ssd'].includes(id));
 $('#more-category').innerHTML='<option value="">More categories</option>'+moreCategories.map(([id,label])=>`<option value="${id}"${id===activeCategory?' selected':''}>${label}</option>`).join('');
 const currentMore=moreCategories.find(([id])=>id===activeCategory);
 $('#category-menu-label').textContent=currentMore?.[1]||'Choose a category';
 $('#category-menu-icon').innerHTML=icon(currentMore?.[0]||'all');
 $('#category-menu-options').innerHTML=moreCategories.map(([id,label])=>`<button type="button" data-category="${id}" class="${id===activeCategory?'active':''}" aria-pressed="${id===activeCategory}"><span class="category-option-icon" aria-hidden="true">${icon(id)}</span><span><strong>${escapeHTML(label)}</strong><small>${escapeHTML(categoryHelp[id]||'Compare available specifications')}</small></span><span class="category-option-count">${catalog.filter(p=>p.cat===id).length}</span></button>`).join('');
 const keys=[...new Set(ps.flatMap(p=>Object.keys(p.specs)))],preferred={cpu:['CPU cores','Boost clock','CPU TDP'],ram:['Memory','Transfer rate','CAS latency'],ssd:['Storage capacity','Sequential read','Sequential write']}[activeCategory]||['Memory','Memory bandwidth','Board power'];
 let charts=preferred.filter(k=>keys.includes(k));if(!charts.length)charts=keys.slice(0,3);
 $('#metric-grid').innerHTML=charts.map(key=>{const max=Math.max(...ps.map(p=>Number(p.specs[key])||0),1);return `<article class="metric-card"><h3>${escapeHTML(key)} <span>${units[key]||''}</span></h3>${ps.map((p,i)=>`<div class="metric-row"><div><span>${escapeHTML(shortName(p))}</span><strong>${number(p.specs[key])}</strong></div><div class="metric-track">${p.specs[key]!==undefined?`<span style="width:${Math.max(0,Number(p.specs[key])/max*100)}%;background:${series[i]}"></span>`:''}</div></div>`).join('')}</article>`}).join('')||'<p class="empty-message">Add a part to see its specifications.</p>';
 const onlyDiff=$('#differences-only').checked,rows=keys.filter(k=>!onlyDiff||new Set(ps.map(p=>p.specs[k])).size>1);
 const metadata=[['Architecture',p=>p.architecture],['Release year',p=>p.year||'Unavailable']].filter(([,get])=>!onlyDiff||new Set(ps.map(get)).size>1);
 $('#spec-count').textContent=(rows.length+metadata.length)+' fields';
 $('#comparison-table').innerHTML=ps.length?`<table><thead><tr><th scope="col">Specification</th>${ps.map(p=>`<th scope="col">${escapeHTML(shortName(p))}</th>`).join('')}</tr></thead><tbody>${rows.map(k=>`<tr><th scope="row">${escapeHTML(k)}</th>${ps.map(p=>`<td>${escapeHTML(value(p,k))}</td>`).join('')}</tr>`).join('')}${metadata.map(([label,get])=>`<tr><th scope="row">${label}</th>${ps.map(p=>`<td>${escapeHTML(get(p))}</td>`).join('')}</tr>`).join('')}${!rows.length&&!metadata.length?`<tr><td colspan="${ps.length+1}">No differences in the available specifications.</td></tr>`:''}</tbody></table>`:'<p class="empty-message">Your comparison is empty. Add a part to begin.</p>';
 $('#comparison-warning').innerHTML=new Set(ps.map(p=>p.cat)).size>1?'<p class="notice">Different hardware categories use specifications differently. Shared memory and dedicated VRAM, for example, are not interchangeable.</p>':'';
 $('#comparison-sources').innerHTML=ps.map(p=>{const a=photos[p.id];return `<article><strong>${escapeHTML(p.name)}</strong><p>${escapeHTML(p.note||'Reference specifications. Exact configurations and partner models may differ.')}</p><a href="${escapeHTML(p.source)}" target="_blank" rel="noopener">Specification source ↗</a>${a?`<p>Pictured: ${escapeHTML(a.picturedModel)}.${a.kind!=='exact'?' The selected model may look different.':''}</p>${imageCredits(a)}`:''}</article>`;}).join('')+'<p>A dash means unavailable. <a href="/methodology/">About the data →</a></p>';
 saveComparison();renderEvent('comparison');
}
let replacing=null,pickerCategory=null,returnFocus=null;
function openPicker(index=null,category=activeCategory){replacing=index;pickerCategory=category;returnFocus=document.activeElement;$('#picker-query').value='';$('#picker-category-label').textContent=categories.find(([id])=>id===category)?.[1]||'All hardware';$('#part-picker').showModal();renderPicker();$('#picker-query').focus();}
function closePicker(){$('#part-picker').close();if(returnFocus?.isConnected)returnFocus.focus();else $('#add-comparison')?.focus();}
function renderPicker(){const query=$('#picker-query').value.trim().toLowerCase();const rows=catalog.filter(p=>(!pickerCategory||p.cat===pickerCategory)&&!selected.includes(p.id)&&`${p.name} ${p.brand} ${p.architecture}`.toLowerCase().includes(query)).sort((a,b)=>(b.year||0)-(a.year||0));$('#picker-results').innerHTML=rows.length?rows.slice(0,80).map(p=>`<button data-pick="${p.id}">${photos[p.id]?photo(p,'picker-photo'):''}<span class="picker-info"><strong>${escapeHTML(p.name)}</strong><small>${escapeHTML(p.summary)}</small></span><span aria-hidden="true">＋</span></button>`).join(''):'<p class="empty-message">No matches in this category. Try a shorter model name.</p>';}
$('#picker-query').addEventListener('input',renderPicker);$('#close-picker').addEventListener('click',closePicker);
$('#part-picker').addEventListener('click',e=>{if(e.target!==$('#part-picker'))return;const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePicker();});
function exportCSV(){const ps=parts(),keys=[...new Set(ps.flatMap(p=>Object.keys(p.specs)))],quote=v=>'"'+String(v??'Unavailable').replaceAll('"','""')+'"';const rows=[['Specification','Unit',...ps.map(p=>p.name)],...keys.map(k=>[k,units[k]||'',...ps.map(p=>p.specs[k])]),['Source','',...ps.map(p=>p.source)]];const url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='hardware-comparison.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('Comparison exported.');}
function changeCategory(category){activeCategory=category;selected=defaultParts(category);renderComparison();$('#more-category-menu')?.removeAttribute('open');document.querySelector(`[data-category="${category}"]`)?.focus();announce('Showing '+(categories.find(([id])=>id===category)?.[1]||'hardware')+'.');}
if(page==='compare'){
 renderComparison();$('#differences-only').addEventListener('change',renderComparison);$('#add-comparison').addEventListener('click',()=>openPicker());$('#more-category').addEventListener('change',e=>{if(e.target.value)changeCategory(e.target.value);});$('#export-csv').addEventListener('click',exportCSV);
 document.addEventListener('click',e=>{const menu=$('#more-category-menu');if(menu?.open&&!menu.contains(e.target))menu.removeAttribute('open');});
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.remove){selected=selected.filter(id=>id!==b.dataset.remove);renderComparison();$('#add-comparison').focus();announce('Part removed.');}else if(b.dataset.replace!==undefined)openPicker(Number(b.dataset.replace),parts()[Number(b.dataset.replace)].cat);else if(b.dataset.new)openPicker();else if(b.dataset.category)changeCategory(b.dataset.category);else if(b.dataset.pick){if(replacing!==null)selected[replacing]=b.dataset.pick;else if(selected.length<4)selected.push(b.dataset.pick);else{announce('Remove a part before adding another.');return;}renderComparison();closePicker();announce('Comparison updated.');}});
}

if(page==='hardware'){
 try{const saved=JSON.parse(sessionStorage.getItem('pcp-comparison'));if(Array.isArray(saved))selected=validIDs(saved);else selected=[];}catch{selected=[];}
 let limit=24;$('#catalog-category').innerHTML='<option value="all">All hardware</option>'+categories.map(([id,label])=>`<option value="${id}">${label}</option>`).join('');
 const initialCategory=params.get('category')||document.body.dataset.category;if(categories.some(([id])=>id===initialCategory))$('#catalog-category').value=initialCategory;
 $('#catalog-search').value=params.get('q')||'';
 if(['modern','legacy'].includes(params.get('era')))$('#catalog-era').value=params.get('era');if(['old','name'].includes(params.get('sort')))$('#catalog-sort').value=params.get('sort');
 function renderLibrary(){
  const q=$('#catalog-search').value.trim().toLowerCase(),cat=$('#catalog-category').value,era=$('#catalog-era').value,sort=$('#catalog-sort').value;
  const rows=catalog.filter(p=>(cat==='all'||p.cat===cat)&&`${p.name} ${p.brand} ${p.architecture} ${p.summary}`.toLowerCase().includes(q)&&(era==='all'||p.year&&(era==='modern'?p.year>=2020:p.year<2020))).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='old'?(a.year||9999)-(b.year||9999):(b.year||0)-(a.year||0));
  $('#hardware-rows').innerHTML=rows.slice(0,limit).map(p=>`<tr><td><a class="catalog-product" href="/learn/${p.id}.html">${photos[p.id]?photo(p,'catalog-photo'):''}<span class="catalog-product-copy"><strong>${escapeHTML(p.name)}</strong><span>${escapeHTML(p.brand)} · ${escapeHTML(p.architecture)}</span></span></a></td><td>${escapeHTML(categories.find(c=>c[0]===p.cat)?.[1]||p.cat)}</td><td>${p.year||'—'}</td><td>${escapeHTML(p.summary)}</td><td><button class="catalog-add ${selected.includes(p.id)?'chosen':''}" data-library-add="${p.id}" aria-label="${selected.includes(p.id)?'Remove':'Compare'} ${escapeHTML(p.name)}">${selected.includes(p.id)?'✓ Added':'+ Compare'}</button></td></tr>`).join('');
  $('#catalog-summary').textContent=`${Math.min(rows.length,limit)} of ${rows.length.toLocaleString()} parts`;$('#catalog-empty').hidden=!!rows.length;$('#catalog-more').hidden=limit>=rows.length;$('#selected-link').href='/compare/?parts='+selected.join(',');$('#selected-link').textContent=`Compare selected (${selected.length}) →`;
  const categoryTitle=categories.find(([id])=>id===cat)?.[1];$('.page-heading h1').textContent=categoryTitle?categoryTitle+'.':'Explore hardware.';
  const url=new URL(location.href);for(const [key,val,defaultValue] of [['q',q,''],['category',cat,'all'],['era',era,'all'],['sort',sort,'new']]){if(val===defaultValue)url.searchParams.delete(key);else url.searchParams.set(key,val);}history.replaceState(null,'',url);renderEvent('catalog');
 }
 for(const id of ['catalog-search','catalog-category','catalog-era','catalog-sort'])$('#'+id).addEventListener(id==='catalog-search'?'input':'change',()=>{limit=24;renderLibrary();});$('#catalog-more').addEventListener('click',()=>{limit+=36;renderLibrary();});
 document.addEventListener('click',e=>{const b=e.target.closest('[data-library-add]');if(!b)return;const id=b.dataset.libraryAdd;if(selected.includes(id))selected=selected.filter(x=>x!==id);else if(selected.length<4)selected.push(id);else{announce('Four parts selected. Remove one or open the comparison.');return;}try{sessionStorage.setItem('pcp-comparison',JSON.stringify(selected))}catch{}renderLibrary();document.querySelector(`[data-library-add="${id}"]`)?.focus();announce(`${selected.length} parts selected.`);});renderLibrary();
}
function enhanceBuilderPhotos(){if(page!=='builder')return;document.querySelectorAll('.builder-row[data-builder-row]').forEach(row=>{const slot=row.dataset.builderRow,p=buildParts(slot)[0];let el=row.querySelector('.builder-photo');if(el)el.remove();if(p&&photos[p.id]){el=document.createElement('a');el.className='builder-photo';el.href='/learn/'+p.id+'.html';el.setAttribute('aria-label','View '+p.name);el.innerHTML=photo(p,'');row.querySelector('.builder-type').after(el);}});}
if(page==='builder'){
 if(params.has('build')){pcBuild={};const values=params.get('build').split(',');buildSlotDefs.forEach((slot,i)=>{const ids=(values[i]||'').split('~').filter(id=>catalog.some(p=>p.id===id&&p.cat===slot.id));if(ids.length)pcBuild[slot.id]=['cpu','gpu','ram','ssd','hdd','fan'].includes(slot.id)?ids:ids[0];});}if(params.get('compat')==='all')compatibleOnly=false;
 $('#enable-incompatible').addEventListener('change',e=>{compatibleOnly=!e.target.checked;renderBuilder();});
}
if(location.hash){const target=document.getElementById(location.hash.slice(1));if(target?.tagName==='DETAILS')target.open=true;}
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&$('#catalog-search')){e.preventDefault();$('#catalog-search').focus();}});
